if (__antigravityModelPatchUrl) {
  const __antigravityModelPatchSetFlag = (flag) => {
    const i = args.indexOf(flag);
    if (i >= 0) args[i + 1] = __antigravityModelPatchUrl;
    else args.push(flag, __antigravityModelPatchUrl);
  };
  __antigravityModelPatchSetFlag('--api_server_url');
  __antigravityModelPatchSetFlag('--cloud_code_endpoint');
  __antigravityModelPatchSetFlag('--inference_api_server_url');
}
